  box-shadow: 0 7px 32px 0 rgba(28,18,46,0.18), 0 1px 0 rgba(90,0,70,0.06);
  background: linear-gradient(135deg,#232a4d 0%,#2e1246 100%);
  border-radius: 16px;
  margin: 40px auto;
  max-width: 570px;
  padding: 34px 28px 28px 28px;
  position: relative;
}
@media (max-width: 820px) {
  .dream-logger {
    max-width: 97vw;
    padding: 16px 6vw 22px 6vw;
  }
}
@keyframes dreamFadeIn {
  from {
    opacity: 0;
    transform: translateY(40px) scale(.99);
  }
  to {
    opacity: 1;
    transform: none;
  }
}
